async function downloadTemplate(){
 if(typeof XLSX==='undefined'){toast('تعذر تحميل محرك Excel. أعد تحميل الصفحة.','err');return}
 try{
  const rs=await getRegions();
  const ws=XLSX.utils.aoa_to_sheet([['رقم الموظف','اسم الموظف','رقم معاملة التعيين','الإقليم','تاريخ المباشرة'],['','','','','']]);
  ws['!cols']=[{wch:16},{wch:26},{wch:24},{wch:24},{wch:18}];
  const info=XLSX.utils.aoa_to_sheet([['قائمة الأقاليم'],...rs.map(r=>[r])]);info['!cols']=[{wch:35}];
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'نموذج الرفع');XLSX.utils.book_append_sheet(wb,info,'قائمة الأقاليم');
  const out=XLSX.write(wb,{bookType:'xlsx',type:'array'});
  if(typeof JSZip==='undefined')throw Error('تعذر تجهيز نموذج Excel');
  const zip=await JSZip.loadAsync(out);
  const xmlEsc=x=>String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');
  const regionRows=rs.map((r,i)=>`<row r="${i+2}"><c r="A${i+2}" t="inlineStr"><is><t>${xmlEsc(r)}</t></is></c></row>`).join('');
  const sheet2=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><dimension ref="A1:A${Math.max(2,rs.length+1)}"/><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>الإقليم</t></is></c></row>${regionRows}</sheetData></worksheet>`;
  zip.file('xl/worksheets/sheet2.xml',sheet2);
  let sheet1=await zip.file('xl/worksheets/sheet1.xml').async('string');
  const last=Math.max(2,rs.length+1);
  const dv=`<dataValidations count="1"><dataValidation type="list" allowBlank="1" showErrorMessage="1" sqref="D2:D500"><formula1>'قائمة الأقاليم'!$A$2:$A$${last}</formula1></dataValidation></dataValidations>`;
  if(/<dataValidations[\s\S]*?<\/dataValidations>/.test(sheet1))sheet1=sheet1.replace(/<dataValidations[\s\S]*?<\/dataValidations>/,dv);else sheet1=sheet1.replace('</worksheet>',dv+'</worksheet>');
  zip.file('xl/worksheets/sheet1.xml',sheet1);
  const blob=await zip.generateAsync({type:'blob'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='نموذج_رفع_المعاملات.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('تم تنزيل النموذج الموحد');
 }catch(e){toast(e.message||'تعذر إنشاء نموذج Excel','err')}
}
async function importFile(){const f0=document.querySelector('#f')?.files?.[0],msg=document.querySelector('#importMsg');if(!f0){msg.className='inlineMsg err';msg.textContent='اختر ملف Excel أولاً.';return}if(typeof XLSX==='undefined'){msg.className='inlineMsg err';msg.textContent='تعذر تحميل محرك Excel. أعد تحميل الصفحة ثم جرّب مرة أخرى.';return}try{msg.className='inlineMsg';msg.textContent='جاري فحص الملف…';const wb=XLSX.read(await f0.arrayBuffer(),{cellDates:true,raw:false});if(!wb.SheetNames.length)throw Error('الملف لا يحتوي على أي ورقة بيانات.');const sheet=wb.Sheets[wb.SheetNames[0]],raw=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});if(!raw.length)throw Error('الملف فارغ.');const allowed=await getRegions();const rows=raw.map((x,i)=>({row_no:i+2,employee_no:firstVal(x,['رقم الموظف','الرقم الوظيفي','employee number','employee_no','emp']),employee_name:firstVal(x,['اسم الموظف','employee name','employee_name','name']),transaction_no:firstVal(x,['رقم معاملة التعيين','رقم معاملة التعيين/المعاملة','رقم معاملة التوظيف','رقم المعاملة','رقم الطلب','appointment transaction no','appointment_transaction_no','transaction_no']),interruption_transaction_no:firstVal(x,['رقم معاملة الانقطاع أو اتخاذ الإجراء','رقم معاملة الانقطاع','رقم معاملة اتخاذ الإجراء','interruption transaction no','interruption_transaction_no']),region:firstVal(x,['الإقليم','الاقليم','المنطقة','region']),start_date:normalizeDate(firstVal(x,['تاريخ المباشرة','تاريخ مباشرة الموظف','start date','start_date']))}));for(const r of rows){if(r.region&&!allowed.includes(r.region))r.region='';}const d=await api('/api/records/bulk',{method:'POST',body:JSON.stringify({rows})});if(d.skipped){const details=(d.errors||[]).slice(0,6).map(e=>`صف ${e.row}: ${e.reason}`).join(' | ');msg.className='inlineMsg warn';msg.innerHTML=`تم رفع <b>${d.added}</b> معاملة، وتعذر رفع <b>${d.skipped}</b> صف. ${esc(details)}`;return}msg.className='inlineMsg ok';msg.textContent=`تم الرفع بنجاح: ${d.added} معاملة.`;setTimeout(()=>list(),900)}catch(e){msg.className='inlineMsg err';msg.textContent=e.message}}
