async function toggleUser(id){try{await api(`/api/users/${id}`,{method:'POST',body:JSON.stringify({action:'toggle'})});users()}catch(e){toast(e.message,'err')}}
async function loadManagersForDrawer(){const wrap=document.querySelector('#managerSelectWrap');if(!wrap)return;try{const d=await api('/api/managers');wrap.innerHTML=`<label>المسؤول الجديد<select id="reassignManager"><option value="">اختر المسؤول</option>${d.managers.map(m=>`<option value="${m.id}">${esc(m.name)} — ${esc(m.region||'بدون إقليم')}</option>`).join('')}</select></label>`}catch(e){wrap.innerHTML=`<div class="inlineMsg err">${esc(e.message)}</div>`}}

async function loadDelegateManagers(){const wrap=document.querySelector('#delegateManagerWrap');if(!wrap)return;try{const d=await api('/api/managers');wrap.innerHTML=`<label>المسؤول المفوض إليه<select id="delegateManager"><option value="">اختر المسؤول</option>${d.managers.map(m=>`<option value="${m.id}">${esc(m.name)} — ${esc(m.region||'بدون إقليم')}</option>`).join('')}</select></label>`}catch(e){wrap.innerHTML=`<div class="inlineMsg err">${esc(e.message)}</div>`}}
async function delegateRecord(id){const select=document.querySelector('#delegateManager');if(!select?.value){toast('اختر المسؤول المفوض إليه','err');return}const scope=document.querySelector('input[name="delegateScope"]:checked')?.value||'current_future',expires_at=document.querySelector('#delegateExpiry')?.value||null;try{await api(`/api/records/${id}`,{method:'POST',body:JSON.stringify({action:'delegate',region_user_id:Number(select.value),scope,expires_at,note:document.querySelector('#delegateNote')?.value||''})});toast('تم تفعيل التفويض');closeDrawer();list(LIST_MODE)}catch(e){toast(e.message,'err')}}
async function regionsPage(){if(!can('manage_regions')){toast('ليس لديك صلاحية إدارة الأقاليم','err');return}navActive('regions');t.textContent='إدارة الأقاليم';sub.textContent='';const rs=await getRegions();v.innerHTML=`<section class="sectionTitle"><div><h2>الأقاليم</h2><p></p></div></section><section class="formPanel regionAdminPanel"><div class="grid"><label>اسم الإقليم الجديد<input id="newRegion" placeholder="مثال: الرياض"></label></div><button class="primary" onclick="addRegion()">＋ إضافة الإقليم</button></section><section class="regionManageGrid">${rs.length?rs.map(x=>`<article class="regionManageCard"><div class="regionManageIcon">⌖</div><div class="regionManageInfo"><h3>${esc(x)}</h3><small>إقليم نشط</small></div><div class="regionManageActions"><button class="ghost" onclick='editRegion(${JSON.stringify(x)})'>تعديل</button><button class="danger" onclick='deleteRegion(${JSON.stringify(x)})'>حذف</button></div></article>`).join(''):'<div class="empty">لا توجد أقاليم نشطة.</div>'}</section>`}
async function addRegion(){const name=document.querySelector('#newRegion')?.value.trim();if(!name){toast('أدخل اسم الإقليم','err');return}try{await api('/api/regions',{method:'POST',body:JSON.stringify({action:'add',name})});toast('تمت إضافة الإقليم');regionsPage()}catch(e){toast(e.message,'err')}}
async function editRegion(oldName){showInputModal('تعديل الإقليم','اسم الإقليم',oldName,async next=>{try{await api('/api/regions',{method:'POST',body:JSON.stringify({action:'edit',old_name:oldName,name:next})});closeModal();toast('تم تعديل الإقليم');regionsPage()}catch(e){toast(e.message,'err')}})}
async function deleteRegion(name){showConfirmModal('أرشفة الإقليم',`سيتم إخفاء «${name}» من قوائم الاختيار مع الحفاظ على المعاملات التاريخية.`,async()=>{try{await api('/api/regions',{method:'POST',body:JSON.stringify({action:'delete',old_name:name})});closeModal();toast('تمت أرشفة الإقليم');regionsPage()}catch(e){toast(e.message,'err')}})}
function closeModal(){document.querySelector('.modalShade')?.remove()}
function showInputModal(title,label,value,onSave){document.body.insertAdjacentHTML('beforeend',`<div class="modalShade"><div class="modal compactModal"><button class="close" onclick="closeModal()">×</button><span class="eyebrow">إدارة الأقاليم</span><h2>${esc(title)}</h2><label>${esc(label)}<input id="modalInput" value="${esc(value)}" autofocus></label><div class="actionRow"><button class="primary" id="modalSave">حفظ التعديل</button><button class="light" onclick="closeModal()">إلغاء</button></div></div></div>`);document.querySelector('#modalSave').onclick=()=>{const n=document.querySelector('#modalInput').value.trim();if(!n){toast('أدخل اسم الإقليم','err');return}onSave(n)}}
function showConfirmModal(title,text,onOk){document.body.insertAdjacentHTML('beforeend',`<div class="modalShade"><div class="modal compactModal"><button class="close" onclick="closeModal()">×</button><span class="eyebrow">تأكيد الإجراء</span><h2>${esc(title)}</h2><p class="modalText">${esc(text)}</p><div class="actionRow"><button class="danger" id="modalOk">تأكيد</button><button class="light" onclick="closeModal()">إلغاء</button></div></div></div>`);document.querySelector('#modalOk').onclick=onOk}
async function clearTestData(){showConfirmModal('تنظيف بيانات التجربة','سيتم حذف المعاملات التجريبية وسجلها التشغيلي فقط. حسابات المستخدمين والأقاليم لن تتأثر.',async()=>{try{await api('/api/admin/clear-test-data',{method:'POST'});closeModal();toast('تم تنظيف بيانات التجربة');dash()}catch(e){toast(e.message,'err')}})}
async function auditPage(){if(!can('view_audit_log')){toast('ليس لديك صلاحية سجل النشاط','err');return}navActive('audit');t.textContent='سجل النشاط والأمان';sub.textContent='';v.innerHTML='<div class="loading">جاري تحميل السجل…</div>';try{const d=await api('/api/audit');v.innerHTML=`<section class="statsFilter advanced auditFilters"><div class="filterField"><label>بحث</label><input id="aq" placeholder="المستخدم أو النشاط أو التفاصيل"></div><div class="filterField"><label>نوع النشاط</label><select id="aa"><option value="">كل الأنشطة</option><option>تسجيل دخول</option><option>تسجيل خروج</option><option>محاولة دخول فاشلة</option><option>تفويض المعاملة</option><option>إنشاء المعاملة</option><option>إضافة إقليم</option><option>تعديل إقليم</option><option>حذف/أرشفة إقليم</option><option>تصدير التقرير</option></select></div><div class="filterField"><label>من تاريخ</label><input id="af" type="date"></div><div class="filterField"><label>إلى تاريخ</label><input id="at" type="date"></div><button class="primary" onclick="loadAudit()">عرض</button></section><section class="sectionTitle"><div><h2>آخر النشاطات</h2><p>${d.events.length} سجل معروض</p></div>${can('export_audit_log')?`<button class="ghost" onclick="exportAudit()">⇩ تصدير السجل</button>`:''}</section><div id="auditList" class="auditList">${auditEvents(d.events)}</div><section class="sectionTitle" style="margin-top:20px"><div><h2>الجلسات الحالية</h2><p>الجلسات التي لم تنتهِ بعد.</p></div></section><div class="sessionGrid">${d.sessions.map(s=>`<article class="sessionCard"><div><b>${esc(s.name)}</b><small>${esc(roleLabel[s.role]||s.role)}</small></div><span class="pill on">نشط</span><p>الدخول: ${fmtDateTime(s.login_at)}</p><p>آخر نشاط: ${fmtDateTime(s.last_seen_at)}</p></article>`).join('')||empty('لا توجد جلسات نشطة')}</div>`}catch(e){v.innerHTML=`<div class="empty"><b>${esc(e.message)}</b></div>`}}
function auditEvents(rows){return rows.length?rows.map(e=>`<article class="auditEvent"><div class="auditDot"></div><div><div class="auditTop"><b>${esc(e.action)}</b><span>${fmtDateTime(e.created_at)}</span></div><div class="auditActor">${esc(e.actor_name||'النظام')} · ${esc(roleLabel[e.role]||e.role||'')}</div>${e.record_id?`<span class="auditRef">معاملة #${e.record_id}</span>`:''}${e.note?`<p>${esc(e.note)}</p>`:''}</div></article>`).join(''):'<div class="empty">لا توجد سجلات مطابقة</div>'}
async function loadAudit(){const q=document.querySelector('#aq')?.value||'',a=document.querySelector('#aa')?.value||'',from=document.querySelector('#af')?.value||'',to=document.querySelector('#at')?.value||'';try{const d=await api(`/api/audit?q=${encodeURIComponent(q)}&action=${encodeURIComponent(a)}&from=${from}&to=${to}`);document.querySelector('#auditList').innerHTML=auditEvents(d.events)}catch(e){toast(e.message,'err')}}
async function exportAudit(){try{const d=await api('/api/audit/export');const ws=XLSX.utils.json_to_sheet(d.rows);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'سجل النشاط');XLSX.writeFile(wb,`سجل_النشاط_${d.report_date}.xlsx`);toast('تم إصدار سجل النشاط')}catch(e){toast(e.message,'err')}}
async function logout(){await api('/api/logout');ME=null;login()}

// Final UX overrides
async function users(){if(ME.role!=='admin'){toast('للمدير فقط','err');return}navActive('users');t.textContent='المستخدمون والصلاحيات';sub.textContent='';try{const d=await api('/api/users'),regions=await getRegions(),del=can('delegate_records')?await api('/api/delegations'):({delegations:[]});v.innerHTML=`<section class="sectionTitle"><div><h2>الحسابات</h2></div><div class="actionRow"><button class="primary" onclick="userForm()">＋ مستخدم جديد</button>${can('manage_data')?`<button class="danger" onclick="clearTestData()">تنظيف معاملات التجربة</button>`:''}</div></section><div class="userGrid">${d.users.map(x=>userCardFinal(x)).join('')}</div>${can('delegate_records')?`<section class="sectionTitle delegationTitle"><div><h2>التفويضات النشطة</h2><p>تظهر هنا التفويضات التي تغيّر مسؤولية المعاملات الحالية والمستقبلية.</p></div></section><div class="delegationGrid">${(del.delegations||[]).filter(x=>x.rule_type==='delegate').map(x=>`<article class="delegationCard"><div><span class="pill on">تفويض نشط</span><small>#${x.id}</small></div><h3>${esc(x.source_name||'—')} <span>→</span> ${esc(x.target_name||'—')}</h3><p>${x.reason?esc(x.reason):'بدون سبب مسجل'}</p><small>بواسطة ${esc(x.creator_name||'—')} · ${fmtDateTime(x.created_at)}${x.expires_at?` · حتى ${fmtDate(x.expires_at)}`:''}</small><button class="light wide" onclick="cancelDelegation(${x.id})">إنهاء التفويض</button></article>`).join('')||empty('لا توجد تفويضات نشطة')}</div>`:''}`;enhanceSelects()}catch(e){v.innerHTML=`<div class="empty"><b>${esc(e.message)}</b></div>`}}
function userCardFinal(x){const ps=x.permissions||[];return `<article class="userCard"><div class="userHead"><div class="managerAvatar">${esc(x.name?.[0]||'م')}</div><div><h3>${esc(x.name)}</h3><small>${esc(x.username)}</small></div><span class="pill ${x.active?'on':'off'}">${x.active?'مفعل':'معطل'}</span></div><div class="roleLine">${roleLabel[x.role]||x.role}${x.region?` · ${esc(x.region)}`:''}</div><div class="permMini">${ps.length?ps.map(p=>`<span>${esc(permLabels[p]||p)}</span>`).join(''):'<span>لا توجد صلاحيات إضافية</span>'}</div><div class="userActions"><button class="ghost" onclick='userForm(${JSON.stringify(x)})'>تعديل الصلاحيات</button>${x.role==='region'&&x.active&&can('delegate_records')?`<button class="ghost" onclick='userDelegateForm(${JSON.stringify(x)})'>تفويض</button>`:''}<button class="light" onclick="toggleUser(${x.id})">${x.active?'تعطيل':'تفعيل'}</button></div></article>`}
async function userDelegateForm(source){try{const d=await api('/api/managers');const targets=(d.managers||[]).filter(x=>Number(x.id)!==Number(source.id));document.body.insertAdjacentHTML('beforeend',`<div class="modalShade"><div class="modal compactModal"><button class="close" onclick="closeModal()">×</button><span class="eyebrow">تفويض مسؤولية</span><h2>${esc(source.name)}</h2><p class="modalText">سيتم نقل المعاملات المعلقة الحالية، وتحويل المعاملات الجديدة أثناء التفويض.</p><label>المفوض إليه<select id="udTarget"><option value="">اختر المسؤول</option>${targets.map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.region||'بدون إقليم')}</option>`).join('')}</select></label><label>ينتهي التفويض<input id="udExpiry" type="date"></label><label>السبب<input id="udReason" placeholder="مثال: إجازة"></label><div class="actionRow"><button class="primary" onclick="saveDelegation(${source.id})">تفعيل التفويض</button><button class="light" onclick="closeModal()">إلغاء</button></div></div></div>`);enhanceSelects(document.querySelector('.modal'))}catch(e){toast(e.message,'err')}}
async function saveDelegation(sourceId){const target=Number(document.querySelector('#udTarget')?.value||0),expires=document.querySelector('#udExpiry')?.value||null,reason=document.querySelector('#udReason')?.value||'';if(!target){toast('اختر المسؤول المفوض إليه','err');return}try{await api('/api/delegations',{method:'POST',body:JSON.stringify({source_user_id:sourceId,target_user_id:target,expires_at:expires,reason})});closeModal();toast('تم تفعيل التفويض');users()}catch(e){toast(e.message,'err')}}
async function cancelDelegation(id){showConfirmModal('إنهاء التفويض','سيتم إيقاف قاعدة التفويض وإعادة المعاملات المعلقة للمسؤول الأصلي.',async()=>{try{await api(`/api/delegations/${id}`,{method:'POST',body:JSON.stringify({action:'cancel',return_to_source:true})});closeModal();toast('تم إنهاء التفويض');users()}catch(e){toast(e.message,'err')}})}

async function openRecord(id){try{const d=await api(`/api/records/${id}`),r=d.record,events=d.events||[];const end=r.final_approved_at||r.cancelled_at||null;document.body.insertAdjacentHTML('beforeend',`<div class="drawerShade" onclick="closeDrawer(event)"><aside class="drawer" onclick="event.stopPropagation()"><div class="drawerTopActions"><button class="drawerBackBtn" onclick="closeDrawer()">← العودة للمعاملات</button><button class="close" onclick="closeDrawer()" aria-label="إغلاق تفاصيل المعاملة">×</button></div><div class="drawerHead"><div class="drawerMeta"><span class="ref">#${esc(r.id)}</span><span class="status ${r.status}">${esc(r.status_label||statusLabel[r.status]||r.status)}</span></div><h2>${esc(r.employee_name)}</h2><div class="detailChips"><span>رقم الموظف <b>${esc(r.employee_no)}</b></span><span>رقم التعيين <b>${esc(r.transaction_no||'—')}</b></span>${(r.status==='final_withdrawn'||r.status==='region_withdrawn')&&r.interruption_transaction_no?`<span>رقم الانقطاع <b>${esc(r.interruption_transaction_no)}</b></span>`:''}<span>المسؤول الحالي <b>${esc(r.region_user_name||'غير محدد')}</b></span><span>المدة <b class="timerText" data-start="${esc(r.created_at||'')}" data-end="${esc(end||'')}">${esc(r.duration_label||'—')}</b></span></div></div><section class="drawerSection"><h3>بيانات الموظف والمعاملة</h3><div class="infoGrid"><div><small>رقم الموظف</small><b>${esc(r.employee_no)}</b></div><div><small>رقم معاملة التعيين</small><b>${esc(r.transaction_no||'—')}</b></div><div><small>الإقليم</small><b>${esc(r.region||'—')}</b></div><div><small>تاريخ المباشرة</small><b>${fmtDate(r.start_date)}</b></div><div><small>نهاية الدوام</small><b>${fmtDate(r.end_date)}</b></div>${(r.status==='final_withdrawn'||r.status==='region_withdrawn')?`<div><small>رقم معاملة الانقطاع أو اتخاذ الإجراء</small><b>${esc(r.interruption_transaction_no||'—')}</b></div>`:''}<div><small>مقدم الطلب</small><b>${esc(r.requester_name||'—')}</b></div></div></section>${r.region_note?`<section class="noteBlock"><div><b>إفادة مسؤول الإقليم</b><span>${fmtDateTime(r.region_responded_at)}</span></div><p>${esc(r.region_note)}</p></section>`:''}${r.requester_note?`<section class="noteBlock final"><div><b>ملاحظة HR / الاعتماد</b></div><p>${esc(r.requester_note)}</p></section>`:''}${await actionsFor(r)}<section class="drawerSection"><div class="sectionInline"><h3>سجل المتابعة</h3><span class="mutedSmall">${events.length} أحداث</span></div><div class="timeline">${events.length?events.map(e=>`<div class="event"><i></i><div><b>${esc(e.action)}</b>${e.note?`<p>${esc(e.note)}</p>`:''}<small>${fmtDateTime(e.created_at)} · ${esc(e.actor_name||'النظام')}</small></div></div>`).join(''):'<small>لا يوجد سجل بعد</small>'}</div></section></aside></div>`);if(can('reassign_records'))loadManagersForDrawer();if(can('delegate_records'))loadDelegateManagers();startTimers()}catch(e){toast(e.message,'err')}}
boot();
